mapper.sql:
WHERE invoice.status > 0

    AND (
    invoice.order_code LIKE CONCAT('%', #{filter.searchText}, '%')
    OR customers.name_kh LIKE CONCAT('%', #{filter.searchText}, '%')
    OR customers.name LIKE CONCAT('%', #{filter.searchText}, '%')
    )


    AND invoice.order_date >= #{filter.dateFrom}


    AND invoice.order_date <= #{filter.dateTo}


    AND invoice.status = #{filter.status}


    AND invoice.company_id = #{filter.companyId}


    AND invoice.customer_id = #{filter.organizationId}


    AND invoice.customer_id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id = #{filter.organizationGroupId})


    AND product_pgroups.pgroup_id = #{filter.productGroupId}
